import{_ as r}from"./chunks/Audio.COine8Wh.js";import{c as t,o as n,j as i,G as o,ae as a,a as s}from"./chunks/framework.Bw0Gm4PQ.js";const u=JSON.parse('{"title":"Immediate Measures to Increase American Mineral Production","description":"","frontmatter":{"legisId":"2025-03-20-immediate-measures-to-increase-american-mineral-production","title":"Immediate Measures to Increase American Mineral Production","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/03/immediate-measures-to-increase-american-mineral-production/","publishDate":"2025-03-20T17:36:03-04:00"},"headers":[],"relativePath":"executive-orders/2025-03-20-immediate-measures-to-increase-american-mineral-production.md","filePath":"executive-orders/2025-03-20-immediate-measures-to-increase-american-mineral-production.md"}'),l={name:"executive-orders/2025-03-20-immediate-measures-to-increase-american-mineral-production.md"},g=Object.assign(l,{setup(c){return(d,e)=>(n(),t("div",null,[e[0]||(e[0]=i("h1",{id:"immediate-measures-to-increase-american-mineral-production",tabindex:"-1"},[s("Immediate Measures to Increase American Mineral Production "),i("a",{class:"header-anchor",href:"#immediate-measures-to-increase-american-mineral-production","aria-label":'Permalink to "Immediate Measures to Increase American Mineral Production"'},"​")],-1)),o(r),e[1]||(e[1]=a('<p>Published on Thursday, March 20, 2025</p><ul><li><p><strong>Purpose</strong>: The executive order aims to boost domestic mineral production for job creation, economic prosperity, and national security, reducing reliance on foreign mineral sources.</p></li><li><p><strong>Definitions</strong>:</p><ul><li><strong>Mineral</strong>: Includes critical minerals, uranium, copper, potash, gold, and other materials as defined by the National Energy Dominance Council (NEDC).</li><li><strong>Mineral Production</strong>: Encompasses the mining, processing, refining, and manufacturing of minerals and their derivatives.</li><li><strong>Processed Minerals</strong>: Minerals converted into usable forms (e.g., metals, alloys).</li><li><strong>Derivative Products</strong>: Goods incorporating processed minerals, such as electronics and renewable energy components.</li></ul></li><li><p><strong>Action Steps</strong>:</p><ul><li><strong>Expedited Approval</strong>: Departments and agencies to identify mineral projects and prioritize permits for immediate approval within specified timelines.</li><li><strong>Transparency Projects</strong>: Projects for expedited review to be identified for public access on the Permitting Dashboard.</li><li><strong>Regulatory Feedback</strong>: The NEDC will solicit industry input on regulatory challenges.</li></ul></li><li><p><strong>Land Management</strong>:</p><ul><li><strong>Federal Lands</strong>: The Secretary of the Interior to prioritize mining on federal lands known to hold mineral deposits.</li><li><strong>Site Identification</strong>: Relevant secretaries to identify federal lands suitable for mineral production and expedite leasing processes.</li></ul></li><li><p><strong>Support for Development</strong>:</p><ul><li><strong>Leasing Agreements</strong>: Secretaries of Defense and Energy to establish leases with private entities for mineral production.</li><li><strong>Loan Access</strong>: Collaboration among agencies to facilitate favorable loan terms for mineral production projects.</li></ul></li><li><p><strong>Investment Facilitation</strong>:</p><ul><li><strong>Private Capital Coordination</strong>: The Department of Defense to connect private capital with domestic mineral production projects.</li><li><strong>Funding Plans</strong>: Development of a dedicated fund for mineral production through the United States International Development Finance Corporation (DFC).</li></ul></li><li><p><strong>Legislative Framework</strong>:</p><ul><li><strong>Recommendations to Congress</strong>: Joint recommendation on waste disposal regulations related to mineral extraction to be submitted.</li><li><strong>Policy Rescission</strong>: Federal agencies to remove obstructive policies regarding funding applications for mineral production.</li></ul></li><li><p><strong>Implementation Notes</strong>:</p><ul><li>The order reaffirms existing authorities and functions of executive departments and agencies.</li><li>It is subject to available appropriations and does not create enforceable rights against the federal government.</li></ul></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/03/immediate-measures-to-increase-american-mineral-production/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/03/immediate-measures-to-increase-american-mineral-production/</a></p>',3))]))}});export{u as __pageData,g as default};
